<script setup lang="ts">
import { computed } from 'vue'
import { Copy, List, CalendarDays, Pencil, ArrowLeftRight, Minus } from '@lucide/vue'
import { ArrowLeft, ArrowRight, ArrowUp, Bookmark, Check, CheckCheck, ChevronDown, ChevronRight, CircleUserRound, Clock3, House, Image, Layers, LayoutGrid, Map, MapPin, MessageCircle, Moon, Search, Send, Settings, Share2, SlidersHorizontal, Sparkles, Star, Wallet, X, Heart, Bike, BriefcaseBusiness, ChartNoAxesCombined, History, Bell, Scale, LocateFixed, Wifi, Refrigerator, WashingMachine, AirVent, Flame, LockKeyhole, Sun, Coffee, CircleHelp, Plus, RefreshCw, LoaderCircle, BedDouble } from '@lucide/vue'
const props = withDefaults(defineProps<{ name: string; size?: number }>(), { size: 20 })
const icons: Record<string, typeof ArrowLeft> = { 'arrow-left': ArrowLeft, 'arrow-right': ArrowRight, 'arrow-up': ArrowUp, bookmark: Bookmark, check: Check, 'check-check': CheckCheck, 'chevron-down': ChevronDown, 'chevron-right': ChevronRight, user: CircleUserRound, 'circle-user-round': CircleUserRound, clock: Clock3, 'clock-3': Clock3, home: House, house: House, image: Image, layers: Layers, grid: LayoutGrid, 'layout-grid': LayoutGrid, map: Map, 'map-pin': MapPin, message: MessageCircle, 'message-circle': MessageCircle, moon: Moon, search: Search, send: Send, settings: Settings, share: Share2, 'share-2': Share2, sliders: SlidersHorizontal, 'sliders-horizontal': SlidersHorizontal, sparkles: Sparkles, star: Star, wallet: Wallet, x: X, heart: Heart, bike: Bike, briefcase: BriefcaseBusiness, chart: ChartNoAxesCombined, history: History, bell: Bell, scale: Scale, locate: LocateFixed, 'locate-fixed': LocateFixed, wifi: Wifi, refrigerator: Refrigerator, 'washing-machine': WashingMachine, 'air-vent': AirVent, flame: Flame, lock: LockKeyhole, sun: Sun, coffee: Coffee, help: CircleHelp, plus: Plus, refresh: RefreshCw, loader: LoaderCircle, bed: BedDouble }
const extraIcons: Record<string, typeof ArrowLeft> = { copy: Copy, list: List, calendar: CalendarDays, pencil: Pencil, swap: ArrowLeftRight, minus: Minus }
const icon = computed(() => icons[props.name] ?? extraIcons[props.name] ?? Sparkles)
</script>
<template><component :is="icon" :size="size" :stroke-width="1.65" aria-hidden="true" /></template>
